        return 1
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % MOD
    return result

def inverse_factorial(n):
    return pow(factorial(n), MOD - 2, MOD)

def count_permutations(groups):
    total_permutations = 1
    for group_size in groups.values():
