        for key in current_groups.keys():
            new_groups = current_groups.copy()
            del new_groups[key]
            ways = dfs(new_groups)
            total_ways = (total_ways + ways * count_permutations({key: current_groups[key]})) % MOD

        return total_ways

    return dfs(groups)

